/** Authored, illustrative working notes. No scenario implies a client engagement. */
export type TopicDraft = {
  name: string
  decision: string
  approach?: string
  artifact?: string
  scenario?: string
  validation?: string
  value?: string
}

// Each line is a complete editorial record, separated from navigation and rendering.
function topics(source: string): TopicDraft[] {
  return source
    .trim()
    .split('\n')
    .map((line) => {
      const fields = line.split('|').map((field) => field.trim())
      if (fields.length !== 7 || fields.some((field) => !field)) {
        throw new Error(`Incomplete Process topic: ${fields[0]}`)
      }
      const [name, decision, approach, artifact, scenario, validation, value] =
        fields
      return { name, decision, approach, artifact, scenario, validation, value }
    })
}

